styleBlocks:
html, body, #root { margin: 0px; width: 100%; height: 100%; }
#root { opacity: 0; transition: opacity 0.16s; }
body.zcode-startup-ready #root { opacity: 1; }
#loading { position: fixed; inset: 0px; z-index: 2147483647; display: flex; align-items: center; justify-content: center; transition: opacity 0.16s; }
body.zcode-startup-ready #loading { pointer-events: none; opacity: 0; }
.startup-logo-shell { position: relative; display: flex; width: 96px; height: 96px; align-items: center; justify-content: center; border-radius: 24px; background: linear-gradient(rgb(0, 0, 0) 0%, rgb(21, 23, 24) 100%); box-shadow: rgba(0, 0, 0, 0.2) 0px 20px 25px -5px, rgba(0, 0, 0, 0.2) 0px 8px 10px -6px; transform: scale(0.72); opacity: 0; animation: 0.72s cubic-bezier(0.22, 1, 0.36, 1) 0s 1 normal forwards running startup-logo-pop; transform-origin: center center; }
.startup-logo-shell::before { position: absolute; inset: 0px; pointer-events: none; content: ""; border: 1px solid rgba(255, 255, 255, 0.1); border-radius: inherit; }
.startup-logo { width: 56px; height: auto; color: rgb(255, 255, 255); }
@keyframes startup-logo-pop { 
  0% { opacity: 0; transform: scale(0.72); }
  38% { opacity: 1; transform: scale(1.045); }
  58% { transform: scale(0.985); }
  76% { transform: scale(1.008); }
  100% { opacity: 1; transform: scale(1); }
}
@media (prefers-reduced-motion: reduce) {
  .startup-logo-shell { opacity: 1; transform: scale(1); animation: auto ease 0s 1 normal none running none; }
}

