html,
body,
#root {
  margin: 0;
  width: 100%;
  height: 100%;
}

#root {
  opacity: 0;
  transition: opacity 0.16s ease;
}

body.zcode-startup-ready #root {
  opacity: 1;
}

#loading {
  position: fixed;
  inset: 0;
  z-index: 2147483647;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.16s ease;
}

body.zcode-startup-ready #loading {
  pointer-events: none;
  opacity: 0;
}

.startup-logo-shell {
  position: relative;
  display: flex;
  width: 96px;
  height: 96px;
  align-items: center;
  justify-content: center;
  border-radius: 24px;
  background: linear-gradient(180deg, #000000 0%, #151718 100%);
  box-shadow:
    0 20px 25px -5px rgb(0 0 0 / 0.2),
    0 8px 10px -6px rgb(0 0 0 / 0.2);
  transform: scale(0.72);
  opacity: 0;
  animation: startup-logo-pop 0.72s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  transform-origin: center;
}

.startup-logo-shell::before {
  position: absolute;
  inset: 0;
  pointer-events: none;
  content: "";
  /* 修复原因：启动 logo 壳是固定深色底，边框不能跟随浅色主题 token，否则首屏边框过重。 */
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: inherit;
}

.startup-logo {
  width: 56px;
  height: auto;
  color: #ffffff;
}

@keyframes startup-logo-pop {
  0% {
    opacity: 0;
    transform: scale(0.72);
  }

  38% {
    opacity: 1;
    transform: scale(1.045);
  }

  58% {
    transform: scale(0.985);
  }

  76% {
    transform: scale(1.008);
  }

  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .startup-logo-shell {
    opacity: 1;
    transform: scale(1);
    animation: none;
  }
}

